#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; source "$SCRIPT_DIR/network_discovery.sh"; REPORT=${1:?Uso: $0 <pasta_do_relatorio>}; mkdir -p "$REPORT"; IFACE_LAN=$(select_lan_interface); RANGE=$(select_scan_range "$IFACE_LAN" "${SCAN_RANGE:-}"); record_interface_selection "$REPORT" "$IFACE_LAN" "$RANGE"; ( sudo timeout 60 p0f -i "$IFACE_LAN" -o "$REPORT/p0f.log" ) & pid=$!; sudo nmap -sn -e "$IFACE_LAN" --script broadcast-ssdp-discover,broadcast-dns-service-discovery -oN "$REPORT/broadcast.nmap"; sudo nbtscan -r "$RANGE" > "$REPORT/netbios.txt"; avahi-browse -at --terminate > "$REPORT/mdns.txt"; test -s "$REPORT/mdns.txt"; wait "$pid"; test -s "$REPORT/p0f.log"; test -s "$REPORT/broadcast.nmap"